Object.assign(SNIP,{});PRESET_NOTES["l3"]={"Ví dụ: Bất biến của tìm lớn nhất": "Vùng tô màu là đoạn a[0..i-1]; ở đầu mỗi lần lặp, lonNhat luôn là số lớn nhất của vùng đó. Dãy toàn số âm vẫn cho kết quả đúng vì lonNhat khởi tạo bằng a[0].", "Ví dụ: Bất biến của tính tổng": "Khởi tạo: i = 0, đoạn rỗng có tổng 0. Duy trì: cộng thêm a[i] thì tong là tổng của a[0..i]. Kết thúc: i = n, tong là tổng cả dãy.", "Bẫy: khởi tạo lớn nhất bằng 0": "Chạy đúng với mọi dãy có số dương, nhưng với dãy toàn số âm in ra 0, số không có trong dãy. Bước “khởi tạo” của bất biến bị vi phạm.", "Bẫy: tràn số khi tính tổng bằng int": "Ba tỷ vượt phạm vi int (tối đa 2 147 483 647) nên bị quay vòng thành số âm. long long chứa được tới khoảng 9,2 · 10^18.", "Ví dụ: Kiểm tra dãy tăng dần": "Bất biến: đoạn a[0..i-1] tăng dần. Chỉ cần một cặp liền kề không tăng là đủ kết luận, nên dừng sớm bằng break. Chú ý dãy có hai số 4 bằng nhau: tăng NGẶT thì không đạt."};EX_HINTS["l3"]=[["Chỉ cần nhớ số đứng ngay trước; so sánh với x <= truoc (bằng nhau cũng không đạt).", "Vẫn đọc hết dữ liệu (không break khi đọc) cho gọn; n = 1 thì luôn YES."], ["Code mẫu đúng ý tưởng nhưng sai kiểu dữ liệu: ước lượng tổng lớn nhất là 10^5 · 10^9 = 10^14.", "Đổi tong sang long long. Số 2147483647 + 1 cũng vượt int."], ["Bất biến: khi xét ngày j, nhoNhat là giá thấp nhất trong các ngày TRƯỚC j.", "Lãi nếu bán ở ngày j là a[j] - nhoNhat; giữ giá trị lớn nhất của nó.", "Cập nhật lãi trước rồi mới cập nhật nhoNhat, để không mua và bán cùng một ngày."]];
