const PR3=[{label:"Ví dụ: Bất biến của tìm lớn nhất",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> a = {-7, -3, -9, -1, -6, -4};\n    int n = a.size();\n    int lonNhat = a[0];\n    // bất biến: lonNhat = lớn nhất của a[0..i-1]\n    for (int i = 1; i < n; i++) {\n        if (a[i] > lonNhat) {\n            lonNhat = a[i];\n        }\n    }\n    cout << lonNhat << \"\\n\";\n    return 0;\n}",viz:[{type:"bars",of:"a",ptr:["i"],range:["0","i-1"]},{type:"vars",names:["lonNhat"]}],predict:[{line:12,v:"lonNhat",val:true,q:"lonNhat sẽ thành giá trị nào? Bấm vào cột có giá trị đó."}],py:{code:"a = [-7, -3, -9, -1, -6, -4]\nn = len(a)\nlonNhat = a[0]\n# bất biến: lonNhat = lớn nhất của a[0..i-1]\nfor i in range(1, n):\n    if a[i] > lonNhat:\n        lonNhat = a[i]\nprint(lonNhat)",predict:[{line:7,v:"lonNhat",val:true,q:"lonNhat sẽ thành giá trị nào? Bấm vào cột có giá trị đó."}]},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] a = { -7, -3, -9, -1, -6, -4 };\n        int n = a.Length;\n        int lonNhat = a[0];\n        // bất biến: lonNhat = lớn nhất của a[0..i-1]\n        for (int i = 1; i < n; i++)\n        {\n            if (a[i] > lonNhat)\n            {\n                lonNhat = a[i];\n            }\n        }\n        Console.WriteLine(lonNhat);\n    }\n}",predict:[{line:15,v:"lonNhat",val:true,q:"lonNhat sẽ thành giá trị nào? Bấm vào cột có giá trị đó."}]}},{label:"Ví dụ: Bất biến của tính tổng",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> a = {4, 8, 15, 16, 23, 42};\n    int n = a.size();\n    long long tong = 0;\n    // bất biến: tong = a[0] + a[1] + ... + a[i-1]\n    for (int i = 0; i < n; i++) {\n        tong += a[i];\n    }\n    cout << tong << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"a",ptr:["i"],range:["0","i-1"]},{type:"vars",names:["tong"]}],py:{code:"a = [4, 8, 15, 16, 23, 42]\nn = len(a)\ntong = 0\n# bất biến: tong = a[0] + a[1] + ... + a[i-1]\nfor i in range(n):\n    tong += a[i]\nprint(tong)"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] a = { 4, 8, 15, 16, 23, 42 };\n        int n = a.Length;\n        long tong = 0;\n        // bất biến: tong = a[0] + a[1] + ... + a[i-1]\n        for (int i = 0; i < n; i++)\n        {\n            tong += a[i];\n        }\n        Console.WriteLine(tong);\n    }\n}"}},{label:"Bẫy: khởi tạo lớn nhất bằng 0",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> a = {-7, -3, -9};\n    int lonNhat = 0;\n    for (int x : a) {\n        if (x > lonNhat) lonNhat = x;\n    }\n    cout << lonNhat << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"a"},{type:"vars",names:["x","lonNhat"]}],py:{code:"a = [-7, -3, -9]\nlonNhat = 0\nfor x in a:\n    if x > lonNhat:\n        lonNhat = x\nprint(lonNhat)"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] a = { -7, -3, -9 };\n        int lonNhat = 0;\n        foreach (int x in a)\n        {\n            if (x > lonNhat) lonNhat = x;\n        }\n        Console.WriteLine(lonNhat);\n    }\n}"}},{label:"Bẫy: tràn số khi tính tổng bằng int",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> a = {1000000000, 1000000000, 1000000000};\n    int tong = 0;\n    for (int x : a) tong += x;\n    cout << \"int: \" << tong << \"\\n\";\n    long long tong2 = 0;\n    for (int x : a) tong2 += x;\n    cout << \"long long: \" << tong2 << \"\\n\";\n    return 0;\n}",viz:[{type:"vars",names:["tong","tong2"]}],py:{label:"Bẫy: số thực không chính xác tuyệt đối",code:"a = [0.1] * 10\ntong = 0\nfor x in a:\n    tong += x\nprint(tong)\nprint(tong == 1.0)\ntong2 = 0\nfor x in [1] * 10:\n    tong2 += x\nprint(tong2 / 10 == 1.0)",viz:[{type:"vars",names:["tong","tong2"]}],note:"Số nguyên Python không bao giờ tràn, nhưng số thực (float) thì làm tròn: cộng 0.1 mười lần được 0.9999999999999999, không bằng 1.0. Khi có thể, hãy tính bằng số nguyên rồi mới chia ở bước cuối."},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] a = { 1000000000, 1000000000, 1000000000 };\n        int tong = 0;\n        foreach (int x in a) tong += x;\n        Console.WriteLine(\"int: \" + tong);\n        long tong2 = 0;\n        foreach (int x in a) tong2 += x;\n        Console.WriteLine(\"long: \" + tong2);\n    }\n}",note:"int của C# chứa tới khoảng 2,1 · 10⁹; vượt quá thì giá trị quay vòng sang số âm mà chương trình không báo lỗi gì. long chứa tới khoảng 9,2 · 10¹⁸."}},{label:"Ví dụ: Kiểm tra dãy tăng dần",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> a = {1, 3, 4, 4, 7};\n    bool tang = true;\n    for (int i = 1; i < (int)a.size(); i++) {\n        if (a[i] <= a[i - 1]) {\n            tang = false;\n            break;\n        }\n    }\n    cout << (tang ? \"Tang dan\" : \"Khong tang dan\") << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"a",ptr:["i"],range:["0","i-1"]}],py:{code:"a = [1, 3, 4, 4, 7]\ntang = True\nfor i in range(1, len(a)):\n    if a[i] <= a[i - 1]:\n        tang = False\n        break\nprint(\"Tang dan\" if tang else \"Khong tang dan\")"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] a = { 1, 3, 4, 4, 7 };\n        bool tang = true;\n        for (int i = 1; i < a.Length; i++)\n        {\n            if (a[i] <= a[i - 1])\n            {\n                tang = false;\n                break;\n            }\n        }\n        Console.WriteLine(tang ? \"Tang dan\" : \"Khong tang dan\");\n    }\n}"}}];
