makeEx2(document.getElementById("ex-l3"),sim3,[{t:"Dãy tăng ngặt",d:"Đầu vào: n (1 ≤ n ≤ 10^5) rồi n số nguyên. Đầu ra: YES nếu mỗi số lớn hơn hẳn số đứng trước nó, ngược lại NO.",tests:[{in:"5\n1 3 4 6 9",out:"YES"},{in:"5\n1 3 3 6 9",out:"NO"},{in:"1\n5",out:"YES"},{in:"3\n-5 -2 -9",out:"NO"},{in:"2\n-1000000000 1000000000",out:"YES"},{in:"4\n4 3 2 1",out:"NO"}],start:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    // so mỗi số với số đứng trước nó\n    return 0;\n}",perf:{gen:n=>n+"\n"+Array.from({length:n},(_,i)=>i*3).join(" "),ns:[1000,4000,16000],need:"n",limit:n=>14*n+100,why:"Chỉ cần so mỗi số với số liền trước: một lần duyệt."},py:{start:"n = int(input())\na = list(map(int, input().split()))\n# so mỗi số với số đứng trước nó",hints:["So a[i] với a[i - 1] cho i từ 1; bằng nhau cũng không đạt (dùng <=).","n = 1 thì vòng lặp không chạy lần nào và kết quả là YES."]},cs:{start:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = int.Parse(Console.ReadLine());\n        int[] a = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        // so mỗi số với số đứng trước nó\n    }\n}",hints:["So a[i] với a[i - 1] cho i từ 1 tới n - 1; bằng nhau cũng không đạt (a[i] <= a[i - 1]).","n = 1 thì vòng lặp không chạy lần nào và kết quả là YES."]}},{t:"Tổng lớn",d:"Đầu vào: n (1 ≤ n ≤ 10^5) rồi n số nguyên, mỗi số có trị tuyệt đối không quá 10^9. Đầu ra: tổng của chúng.",tests:[{in:"3\n1000000000 1000000000 1000000000",out:"3000000000"},{in:"1\n-7",out:"-7"},{in:"4\n-1000000000 -1000000000 5 -1000000000",out:"-2999999995"},{in:"2\n2147483647 1",out:"2147483648"}],start:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    int tong = 0;\n    for (int i = 0; i < n; i++) {\n        int x;\n        cin >> x;\n        tong += x;\n    }\n    cout << tong << \"\\n\";\n    return 0;\n}",py:{start:"n = int(input())\na = list(map(int, input().split()))\ntong = 0\n# cộng các số vào tong\nprint(tong)",d:"Đầu vào: n (1 ≤ n ≤ 10^5) rồi n số nguyên, mỗi số có trị tuyệt đối không quá 10^9. Đầu ra: tổng của chúng. (Với C++ bài này luyện chọn kiểu long long; số nguyên Python tự lớn theo giá trị nên không lo tràn.)",hints:["Cộng dồn từng số vào tong, bất biến: tong là tổng các số đã xét.","Số nguyên Python không giới hạn độ lớn: 3 · 10^9 hay 10^14 đều đúng. Có thể dùng sum(a)."]},cs:{start:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = int.Parse(Console.ReadLine());\n        int[] a = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        int tong = 0;\n        foreach (int x in a)\n        {\n            tong += x;\n        }\n        Console.WriteLine(tong);\n    }\n}",hints:["Code mẫu đúng ý tưởng nhưng sai kiểu dữ liệu: ước lượng tổng lớn nhất là 10^5 · 10^9 = 10^14.","Đổi tong sang long. Số 2147483647 + 1 cũng vượt int."]}},{t:"Lãi lớn nhất",d:"Giá một mã cổ phiếu trong n ngày là a1, a2, ..., an (n ≤ 10^5, 1 ≤ ai ≤ 10^9). Mua một lần ở ngày i rồi bán ở một ngày j sau đó (i < j). In lãi lớn nhất có thể; nếu ngày nào mua cũng lỗ thì in 0.",tests:[{in:"6\n7 1 5 3 6 4",out:"5"},{in:"5\n7 6 4 3 1",out:"0"},{in:"1\n10",out:"0"},{in:"4\n2 4 1 7",out:"6"},{in:"3\n1000000000 1 1000000000",out:"999999999"}],start:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    // thử mọi cặp (i, j) thì đúng nhưng quá chậm khi n lớn\n    return 0;\n}",perf:{gen:n=>n+"\n"+Array.from({length:n},(_,i)=>((i*7919)%100003)+1).join(" "),ns:[500,1000,2000],need:"n",limit:n=>20*n+100,why:"Thử mọi cặp (i, j) cần khoảng n²/2 phép so sánh. Hãy duyệt một lần, nhớ giá thấp nhất đã gặp."},py:{start:"n = int(input())\na = list(map(int, input().split()))\n# thử mọi cặp (i, j) thì đúng nhưng quá chậm khi n lớn",hints:["Bất biến: khi xét ngày j, nhoNhat là giá thấp nhất trong các ngày TRƯỚC j.","Lãi nếu bán ở ngày j là a[j] - nhoNhat; giữ giá trị lớn nhất của nó.","Cập nhật lãi trước rồi mới cập nhật nhoNhat, để không mua và bán cùng một ngày."]},cs:{start:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = int.Parse(Console.ReadLine());\n        int[] a = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        // thử mọi cặp (i, j) thì đúng nhưng quá chậm khi n lớn\n    }\n}",hints:["Bất biến: khi xét ngày j, nhoNhat là giá thấp nhất trong các ngày TRƯỚC j.","Lãi nếu bán ở ngày j là a[j] - nhoNhat; giữ giá trị lớn nhất của nó.","Cập nhật lãi trước rồi mới cập nhật nhoNhat, để không mua và bán cùng một ngày."]}}]);

